export function getHelmetBrandStats(brand: string) {
  const products = getHelmetProductsForBrand(brand);
  const verified = products.filter(p => p.status === "verified");
  const prices = verified.map(p => p.priceFromPhp).filter((v): v is number => typeof v === "number");
  return { products, verifiedCount: verified.length, minPrice: prices.length ? Math.min(...prices) : undefined, maxPrice: prices.length ? Math.max(...prices) : undefined };
}

export function isIndexableHelmetBrand(brand: string) {
  const stats = getHelmetBrandStats(brand);
  const lineupCount = getHelmetBrandLineup(brand)?.models.length || 0;
  return stats.verifiedCount >= 2 || lineupCount >= 2;
}
export function getHelmetProduct(brand: string, slug: string) {
  return helmetProducts.find(p => p.brandSlug === brand && p.slug === slug);
}
export function getTireProduct(brand: string, slug: string) {
  return tireProducts.find(p => p.brandSlug === brand && p.slug === slug);
}
export function getTopBoxProduct(slug: string) {
  return topBoxProducts.find(p => p.slug === slug);
}
export function getHelmetProductsForBrand(brand: string) {
  return helmetProducts.filter(p => p.brandSlug === brand);
}
export type HelmetCategorySlug = "half-face" | "modular" | "full-face";
export function getHelmetCategoryProducts(slug: HelmetCategorySlug) {
  const verified = helmetProducts.filter(p => p.status === "verified");
  if (slug === "half-face") return verified.filter(p => p.helmetType === "Half face" || p.helmetType === "Open face");
  if (slug === "modular") return verified.filter(p => p.helmetType === "Modular");
  return verified.filter(p => p.helmetType === "Full face");
}

export function normalizeTireSize(value: string) {
  return value.toUpperCase().replace(/\s+/g, "");
}
export function getTireSizeMatches(product: TireProduct) {
  const sizes = new Set(product.knownSizes.map(normalizeTireSize));
  return publicMotorcycles.filter(m => sizes.has(normalizeTireSize(m.frontTire)) || sizes.has(normalizeTireSize(m.rearTire))).map(m => ({
    motorcycle: m,
    frontMatch: sizes.has(normalizeTireSize(m.frontTire)),
    rearMatch: sizes.has(normalizeTireSize(m.rearTire))
  }));
}
export function allCatalogProducts() {
  return [
    ...helmetProducts.filter(p => p.status === "verified").map(p => ({ id:p.id, category:"Helmet", brand:p.brand, model:p.model, slug:`/gear/helmets/${p.brandSlug}/${p.slug}`, detail:p.helmetType, status:p.status })),
    ...tireProducts.filter(p => p.status === "verified").map(p => ({ id:p.id, category:"Tire", brand:p.brand, model:p.model, slug:`/tires/${p.brandSlug}/${p.slug}`, detail:p.useCase, status:p.status })),
    ...topBoxProducts.filter(p => p.status === "verified").map(p => ({ id:p.id, category:"Top box", brand:p.brand, model:p.model, slug:`/accessories/top-box/${p.slug}`, detail:`${p.capacityL}L ${p.shell}`, status:p.status }))
  ];
}

export function getTireProductsForModel(modelId: string) {
  const model = motorcycles.find(m => m.id === modelId);
  if (!model) return [];
  const front = normalizeTireSize(model.frontTire); const rear = normalizeTireSize(model.rearTire);
  return tireProducts
    .filter(p => p.status === "verified" && p.knownSizes.some(s => [front,rear].includes(normalizeTireSize(s))))
    .sort((a, b) => a.brand.localeCompare(b.brand));
}

export function getTopBoxProductsForModel(modelId: string) {
  const exactIds = new Set(getTopBoxFitmentsForModel(modelId).map(fitment => fitment.topBoxId));
  const exact = topBoxProducts.filter(product => product.status === "verified" && exactIds.has(product.id));
  if (exact.length) return exact;

  // Do not show vague, image-less capacity-only research records as shopping products.
  // Research candidates stay in the data layer until their exact product identity and fitment are verified.
  return [];
}
